`timescale 1ns/1ps
module m5_rope_tb#(parameter integer CASE_ID=0,parameter string DATA_DIR="data");
 localparam N=512;reg clk=0,rst_n=0,clear=0,out_ready=0;wire in_ready,out_valid,error;wire signed[23:0]y0,y1;wire[31:0]ic,oc;wire[31:0]sat;
 reg[83:0]fixed_mem[0:N-1];reg[63:0]half_mem[0:N-1];reg[127:0]fp_mem[0:N-1];reg[47:0]exp[0:N-1];integer cycle=0,sent=0,recv=0,mis=0,waits=0,first=-1,firstout=-1,prev=-1,iimin=99999,iimax=0,iv,total;
 wire valid=rst_n&&sent<N;always#5 clk=~clk;
 generate if(CASE_ID==0)hap_rope_pair_s24 dut(.clk(clk),.rst_n(rst_n),.clear(clear),.in_valid(valid),.in_ready(in_ready),.in_x0_s24(fixed_mem[sent][23:0]),.in_x1_s24(fixed_mem[sent][47:24]),.in_cos_s18(fixed_mem[sent][65:48]),.in_sin_s18(fixed_mem[sent][83:66]),.out_valid(out_valid),.out_ready(out_ready),.out_y0_s24(y0),.out_y1_s24(y1),.input_pair_count(ic),.output_pair_count(oc),.saturation_count(sat),.error(error));
 else if(CASE_ID==1)m5_fp16_rope dut(.clk(clk),.rst_n(rst_n),.clear(clear),.in_valid(valid),.in_ready(in_ready),.in_x0_fp16(half_mem[sent][15:0]),.in_x1_fp16(half_mem[sent][31:16]),.in_cos_fp16(half_mem[sent][47:32]),.in_sin_fp16(half_mem[sent][63:48]),.out_valid(out_valid),.out_ready(out_ready),.out_y0_s24(y0),.out_y1_s24(y1),.input_pair_count(ic),.output_pair_count(oc),.error(error));
 else m5_fp32_rope dut(.clk(clk),.rst_n(rst_n),.clear(clear),.in_valid(valid),.in_ready(in_ready),.in_x0_fp32(fp_mem[sent][31:0]),.in_x1_fp32(fp_mem[sent][63:32]),.in_cos_fp32(fp_mem[sent][95:64]),.in_sin_fp32(fp_mem[sent][127:96]),.out_valid(out_valid),.out_ready(out_ready),.out_y0_s24(y0),.out_y1_s24(y1),.input_pair_count(ic),.output_pair_count(oc),.error(error));endgenerate
 initial begin $readmemh({DATA_DIR,"/input_fixed.mem"},fixed_mem);$readmemh({DATA_DIR,"/input_fp16.mem"},half_mem);$readmemh({DATA_DIR,"/input_fp32.mem"},fp_mem);if(CASE_ID==0)$readmemh({DATA_DIR,"/expected_fixed.mem"},exp);else if(CASE_ID==1)$readmemh({DATA_DIR,"/expected_fp16.mem"},exp);else $readmemh({DATA_DIR,"/expected_fp32.mem"},exp);repeat(8)@(posedge clk);rst_n<=1;end
 always@(negedge clk)out_ready<=!((cycle%37)>=25&&(cycle%37)<=31);
 always@(posedge clk)if(rst_n)begin cycle<=cycle+1;if(valid&&in_ready)begin if(first<0)first=cycle;if(prev>=0)begin iv=cycle-prev;if(iv<iimin)iimin=iv;if(iv>iimax)iimax=iv;end prev=cycle;sent<=sent+1;end else if(valid)waits=waits+1;if(error)begin $display("FAIL: M5 error case=%0d",CASE_ID);$finish;end if(out_valid&&out_ready)begin if(firstout<0)firstout=cycle;if({y1,y0}!==exp[recv])begin mis<=mis+1;if(recv<8)$display("MISMATCH M5 case=%0d idx=%0d actual=%012x expected=%012x",CASE_ID,recv,{y1,y0},exp[recv]);end recv<=recv+1;if(recv==N-1)begin total=cycle-first+1;if(mis==0&&{y1,y0}===exp[recv]&&ic==N&&oc==N-1)begin $display("M5_ROPE_METRIC_JSON: {\"case_id\":%0d,\"vectors\":512,\"mismatches\":0,\"ii_min\":%0d,\"ii_max\":%0d,\"first_output_latency\":%0d,\"input_wait_cycles\":%0d,\"total_cycles\":%0d}",CASE_ID,iimin,iimax,firstout-first,waits,total);$display("PASS: M5 RoPE case=%0d",CASE_ID);end else $display("FAIL: M5 final case=%0d mis=%0d in=%0d out=%0d",CASE_ID,mis,ic,oc);$finish;end end if(cycle>10000)begin $display("FAIL: M5 timeout");$finish;end end
endmodule
